pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address alice, address bob, uint256 depositAlice, uint256 depositBob) public {
        // Restrict deposits to reasonable values
        depositAlice = bound(depositAlice, 1, 1e18);
        depositBob = bound(depositBob, 0, 1e18);

        // Ensure alice and bob are distinct from the zero address and from each other
        vm.assume(alice != address(0) && bob != address(0) && alice != bob);

        // Alice deposits
        vm.deal(alice, depositAlice);
        vm.prank(alice);
        c.deposit{value: depositAlice}();

        // Bob may deposit
        if (depositBob > 0) {
            vm.deal(bob, depositBob);
            vm.prank(bob);
            c.deposit{value: depositBob}();
        }

        // Alice withdraws all her credit
        uint256 balanceBefore = address(c).balance;
        vm.prank(alice);
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        // The contract's remaining balance should be exactly depositBob (Bob's unwithdrawn deposit)
        // because Alice's credit was set to zero and the balance should reflect that
        assertTrue(balanceAfter == depositBob, "Balance after Alice's withdrawal should equal Bob's deposit");
    }
}

