        vm.prank(other);
        c.deposit{value: otherAmount}();

        // caller deposits
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // caller withdraws all
        vm.prank(caller);
        c.withdrawAll();

        // Check that the contract balance equals initial + otherAmount (because caller withdrew but balance was not decremented in buggy version)
        // In reference version, after deposit+withdraw of caller, balance = initial + otherAmount - (caller's credit) + caller's credit = initial + otherAmount? Wait, need to think.
        // Actually, after initial: balance = 0; other deposits: balance = otherAmount; caller deposits: balance = otherAmount + depositAmount; caller withdraws: reference: balance = otherAmount + depositAmount - depositAmount = otherAmount; buggy: balance = otherAmount + depositAmount (no decrement).
        // So reference: finalBalance == otherAmount; initial + otherAmount = 0 + otherAmount = otherAmount, holds.
        // But to make a general rule: after other's deposit and caller's deposit+withdraw, the contract balance equals otherAmount plus (if caller withdrew) the amount that would have been deducted in reference. Simpler: reference always satisfies: after any sequence, the contract balance equals sum of all user credits. But that was already tried.
        // Alternative: Compare with initial balance before any deposits? 
        // Let's do: After these operations, the contract balance should be at least the sum of credits of users other than the withdrawer. Since only other has credit remaining, balance >= otherAmount. In reference, balance == otherAmount; in buggy, balance > otherAmount.
        // But that's not a strict equality. Better: after caller withdraws, the contract balance equals the balance before caller deposited (which was otherAmount) because caller's deposit was fully withdrawn. In reference: true; in buggy: false (balance stays higher).
        uint256 prevBalance = address(c).balance - depositAmount; // effectively the balance before caller deposited, which is otherAmount
        // Actually, after other deposit, balance = otherAmount. After caller deposit, balance = otherAmount + depositAmount. Then after caller withdraws, we check.
        // Let's compute directly: 
        // After other deposit: balance = otherAmount
        // After caller deposit: balance = otherAmount + depositAmount
        // After caller withdraw: 
        // Reference: balance = otherAmount + depositAmount - depositAmount = otherAmount
        // Buggy: balance = otherAmount + depositAmount (no subtraction)
        // So the rule: after these operations, the contract balance should equal otherAmount.
        assertTrue(address(c).balance == otherAmount, "Balance should equal other's deposit after caller withdraws");
    }
}

