pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount) public {
        // Bound deposit amount to avoid overflow (reference C uses uint256 arithmetic)
        depositAmount = bound(depositAmount, 0, 1e24);

        // Ensure caller is not the zero address to avoid ETH burn
        vm.assume(caller != address(0));

        // Give caller some ETH
        vm.deal(caller, depositAmount);

        // Perform deposit
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Now withdraw all credit for the same caller
        vm.prank(caller);
        c.withdrawAll();

        // After full withdrawal, the caller's credit should be 0, and the contract's ether balance should be the sum of remaining credits (which is 0 if only one user)
        // For a multi-user scenario, the invariant is: contract.balance >= sum(c.credit(addr)) for all addr
        // But we only have getter for one address; we can check the caller's credit is 0 and balance is >= 0
        // A stronger invariant: after caller's full withdrawal, c.credit(caller) == 0
        // The buggy version does NOT decrement balance, so balance may be > actual credits
        // So the general rule: balance == sum of all credits (we approximate by checking that after one user's full withdrawal, balance >= 0, but that's always true)
        // Instead, use the fact that for any address, after deposit and full withdrawal, the caller's credit is 0.
        // That's true for both versions, but the bug affects balance. 
        // We need a rule that distinguishes: the reference ensures balance is exactly sum of credits, the buggy version breaks that.
        // We can only read public state: credit public mapping gives getter credit(address).
        // The contract's ether balance is address(c).balance.
        // The invariant: sum of all credits (we can't compute it fully) should equal contract balance.
        // But we can test: after a deposit and full withdrawal by a single user, the contract balance should be 0 if that user was the only depositor.
        // However, if other users exist, we can't know. So we must fuzz over a single user scenario.
        // Assume that only this caller interacts.
        // After deposit and full withdrawal, the contract balance should be 0 in reference, but >0 in buggy.
        // So rule: address(c).balance == 0.
        // This holds for reference (balance decremented), fails for buggy (balance not decremented).

        assertTrue(address(c).balance == 0, "Contract balance should be zero after full withdrawal by sole depositor");
    }
}

