pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint depositAmount, uint withdrawFraction) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= 1e30);
        vm.assume(withdrawFraction <= 100);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint expectedWithdraw = depositAmount * withdrawFraction / 100;
        if (expectedWithdraw > 0) {
            vm.prank(caller);
            (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
            vm.assume(success);
            uint finalCredit = c.credit(caller);
            uint expectedCredit = depositAmount - expectedWithdraw;
            assertTrue(finalCredit == expectedCredit);
        } else {
            uint finalCredit = c.credit(caller);
            assertTrue(finalCredit == depositAmount);
        }
    }
}

